import requests, re, numpy as np, pandas as pd
from scipy.spatial import cKDTree
from scipy.optimize import minimize
import matplotlib.pyplot as plt
H={"User-Agent":"openscientist/1.0"}; PROV="/agent/jobs/2fb7d3bc-c93f-41e8-8a0e-1b6aa78e6a58/provenance/"
THREE={'ALA':'A','ARG':'R','ASN':'N','ASP':'D','CYS':'C','GLN':'Q','GLU':'E','GLY':'G','HIS':'H','ILE':'I','LEU':'L','LYS':'K','MET':'M','PHE':'F','PRO':'P','SER':'S','THR':'T','TRP':'W','TYR':'Y','VAL':'V'}
def load(txt,chain=None):
    at={};xyz=[];aa={}
    for ln in txt.split("\n"):
        if ln.startswith("ATOM") and (chain is None or ln[21]==chain):
            r=int(ln[22:26]);p=[float(ln[30:38]),float(ln[38:46]),float(ln[46:54])]
            xyz.append(p);at.setdefault(r,{})[ln[12:16].strip()]=np.array(p);aa[r]=ln[17:20].strip()
    return np.array(xyz),at,aa
def af(acc):
    m=requests.get(f"https://alphafold.ebi.ac.uk/api/prediction/{acc}",headers=H,timeout=90).json()[0]
    t=requests.get(m["pdbUrl"],headers=H,timeout=180).text
    open(PROV+f"af_{acc}.pdb","w").write(t); return t
def chamber_pts(xyz,zn,R=30.,step=2.,raymax=45.,thr=0.90):
    t=cKDTree(xyz); ax=[np.arange(c-R,c+R,step) for c in zn]
    gs=np.stack(np.meshgrid(*ax,indexing="ij"),-1).reshape(-1,3); gs=gs[np.linalg.norm(gs-zn,axis=1)<=R]
    d,_=t.query(gs); cand=gs[d>3.3]
    g=(1+5**.5)/2; dirs=[]
    for i in range(30):
        y=1-2*(i+.5)/30; r=np.sqrt(max(0,1-y*y)); th=2*np.pi*i/g; dirs.append([np.cos(th)*r,y,np.sin(th)*r])
    rr=np.arange(2.,raymax,1.5); hits=np.zeros(len(cand))
    for dv in np.array(dirs):
        pts=cand[:,None,:]+dv[None,None,:]*rr[None,:,None]
        dd,_=t.query(pts.reshape(-1,3)); hits+=(dd.reshape(len(cand),-1)<2.2).any(1)
    return cand[hits/len(dirs)>=thr]
def lining(cav,at,cutoff=6.):
    idx=[];pts=[]
    for r,d in at.items():
        for an,v in d.items():
            if an in ("N","CA","C","O"): continue
            pts.append(v); idx.append(r)
    t=cKDTree(np.array(pts)); near=set()
    for grp in t.query_ball_point(cav,cutoff):
        for k in grp: near.add(idx[k])
    return sorted(near)
POS={"ARG","LYS"}; NEG={"ASP","GLU"}

targets=[("SDD3 (yeast, this work)","Q12496",(60,64,153)),
         ("PITRM1 (human PreP)","Q5JRX3",(104,108,205)),
         ("PreP1 (Arabidopsis)","Q9LJL3",(162,166,262)),
         ("Cym1/PreP (yeast)","P32898",(88,92,185)),
         ("Falcilysin (P. falciparum)","Q8IJB1",None)]
rows=[]
for nm,acc,trip in targets:
    try:
        txt=open(PROV+f"af_{acc}.pdb").read() if acc=="Q12496" else af(acc)
    except Exception as e:
        try: txt=af(acc)
        except Exception as e2: print(nm,"AF fail",repr(e2)); continue
    if acc=="Q12496": txt=open(PROV+"af_Q12496.pdb").read()
    x,a,aa=load(txt)
    if trip is None:
        ks=sorted(a); s="".join(THREE.get(aa[k],'X') for k in ks); m=re.search(r"H..EH",s)
        if not m: print(nm,"no HxxEH"); continue
        h1,h2=ks[m.start()],ks[m.start()+4]
        best=min(((max(np.linalg.norm(a[r]["OE2"]-a[h1]["NE2"]),np.linalg.norm(a[r]["OE2"]-a[h2]["NE2"])),r)
                  for r in a if aa[r]=="GLU" and "OE2" in a[r] and r>h2))
        trip=(h1,h2,best[1]); print(nm,"detected triad",trip,"maxdist %.2f"%best[0])
    try: zl=np.array([a[trip[0]]["NE2"],a[trip[1]]["NE2"],a[trip[2]]["OE2"]])
    except KeyError as e: print(nm,"missing atom",e); continue
    zn=minimize(lambda v: np.sum((np.linalg.norm(zl-v,axis=1)-2.05)**2), zl.mean(0)).x
    fit=np.round(np.linalg.norm(zl-zn,axis=1),2)
    cav=chamber_pts(x,zn)
    if len(cav)==0: print(nm,"no enclosed chamber (open-state model)"); 
    res=lining(cav,a) if len(cav) else []
    comp=[aa[r] for r in res]; ne=sum(c in NEG for c in comp); npz=sum(c in POS for c in comp)
    rows.append(dict(protein=nm,acc=acc,triad=str(trip),zn_fit=str(fit.tolist()),
                     chamber_A3=len(cav)*8,lining=len(res),acidic=ne,basic=npz,net=npz-ne,
                     pct_acidic=round(100*ne/len(res),1) if res else None))
    print(f"{nm:30s} chamber {len(cav)*8:6d} A^3  lining {len(res):4d}  acidic {ne:3d} basic {npz:3d} net {npz-ne:+4d}")
T=pd.DataFrame(rows); print("\n",T.to_string(index=False))
T.to_csv(PROV+"chamber_electrostatics_alphafold.csv",index=False)
fig,ax=plt.subplots(figsize=(8.5,4.4))
c=["#8172B3"]+["#55A868"]*(len(T)-2)+["#C44E52"]
ax.bar(range(len(T)),T.net,color=c[:len(T)])
